     "level": "I",
     "q": "How do you compute a running total?",
     "a": "`SUM(x) OVER (ORDER BY date)` accumulates from the first row to the current one. Add `PARTITION BY` to restart per group (per customer, per month).",
     "e": "The default frame with ORDER BY is `RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW`, so rows with equal order values are summed together. Use `ROWS` for strict row-by-row totals.",
     "code": "WITH daily AS (\n  SELECT o.order_date, SUM(oi.quantity * oi.unit_price) AS revenue\n  FROM orders o JOIN order_items oi ON oi.order_id = o.id\n  WHERE o.status <> 'cancelled' GROUP BY o.order_date\n)\nSELECT order_date, revenue, SUM(revenue) OVER (ORDER BY order_date) AS running_total\nFROM daily LIMIT 6;",
