     "level": "A",
     "q": "What are slowly changing dimensions (SCD)?",
     "a": "Techniques for dimension attributes that change over time. Type 1 overwrites (no history); Type 2 adds a new row with valid-from/valid-to dates and a current flag (full history); Type 3 keeps the previous value in an extra column.",
     "e": "Type 2 lets reports show sales by the customer's city *at the time of the sale*.",
     "code": "CREATE TABLE dim_customer (sk INTEGER PRIMARY KEY, customer_id INTEGER, city TEXT, valid_from TEXT, valid_to TEXT, is_current INTEGER);\nINSERT INTO dim_customer VALUES (1, 1, 'Cuttack', '2023-01-05', '2024-06-30', 0), (2, 1, 'Bhubaneswar', '2024-07-01', '9999-12-31', 1);\nSELECT city FROM dim_customer WHERE customer_id = 1 AND '2024-03-15' BETWEEN valid_from AND valid_to;",
